Here's a complete example:

**XAML:**
```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             x:Class="MyApp.Views.ItemsPage">

    <RefreshView IsRefreshing="{Binding IsRefreshing}"
                 Command="{Binding RefreshCommand}">

        <CollectionView ItemsSource="{Binding Items}"
                        SelectionMode="Single"
                        SelectedItem="{Binding SelectedItem}"
                        SelectionChangedCommand="{Binding ItemSelectedCommand}">
            <CollectionView.ItemTemplate>
                <DataTemplate>
                    <Grid Padding="10">
                        <Label Text="{Binding Name}" FontSize="16" />
                    </Grid>
                </DataTemplate>
            </CollectionView.ItemTemplate>
        </CollectionView>

    </RefreshView>
</ContentPage>
```

**ViewModel:**
```csharp
public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    private ObservableCollection<Item> _items = new();

    [ObservableProperty]
    private bool _isRefreshing;

    [ObservableProperty]
    private Item? _selectedItem;

    public ItemsViewModel(IApiService api, INavigationService nav)
    {
        _api = api;
        _nav = nav;
    }

    [RelayCommand]
    private async Task Refresh()
    {
        var data = await _api.GetItemsAsync();
        Items = new ObservableCollection<Item>(data);
        IsRefreshing = false; // stops the spinner
    }

    [RelayCommand]
    private async Task ItemSelected()
    {
        if (SelectedItem is null) return;

        await _nav.NavigateToAsync("DetailPage",
            new Dictionary<string, object> { ["Item"] = SelectedItem });

        SelectedItem = null; // reset so user can re-select same item
    }
}
```

**Key binding points:**

| XAML Property | ViewModel Property | Purpose |
|---|---|---|
| `IsRefreshing` | `IsRefreshing` | Controls refresh spinner; set `false` when done |
| `Command` (RefreshView) | `RefreshCommand` | Triggered on pull-to-refresh |
| `ItemsSource` | `Items` | The data collection |
| `SelectedItem` | `SelectedItem` | Two-way; holds current selection |
| `SelectionChangedCommand` | `ItemSelectedCommand` | Fires on tap to trigger navigation |

**Important notes:**
- Set `SelectedItem = null` after navigation so the same item can be re-selected.
- Set `IsRefreshing = false` at the end of your refresh logic to dismiss the spinner.
- `SelectionMode="Single"` ensures only one item highlights at a time.
- The `[RelayCommand]` source generator (MVVM Toolkit) auto-creates `RefreshCommand` and `ItemSelectedCommand`.
